def flatten_bindings(bindings: dict[str, dict[str, str]]) -> list[str]:
    flattened_ledger = []
    for section, section_ledger in bindings.items():
        for key, value in section_ledger.items():
            flattened_ledger.append(f"{section}.{key}={value}")
    return flattened_ledger


